#include "game_engine.hpp"
#include <numeric>
namespace remora {
void GameEngine::missing(){int d=s.difficulty,len=std::min(24,(int[]){3,4,6,8,10}[d]+(s.level-1)/3);s.sequence=pattern(len);s.gaps.resize(len);std::iota(s.gaps.begin(),s.gaps.end(),0);shuffle(s.gaps);s.gaps.resize(std::min(6,(int[]){1,1,2,3,3}[d]+extra()));std::sort(s.gaps.begin(),s.gaps.end());s.order.resize(len);std::iota(s.order.begin(),s.order.end(),0);if(d==4)std::reverse(s.order.begin(),s.order.end());for(int i:s.order)if(has(s.gaps,i))s.answers.push_back(s.sequence[i]);missingPlayback(false);}
void GameEngine::missingPlayback(bool replay){cancel();auto order=s.order;if(!replay)std::sort(order.begin(),order.end());int interval=std::lround((int[]){750,600,380,270,195}[s.difficulty]*pace());s.phase=replay?Phase::MissingReplay:Phase::MissingWatch;s.pulse=0;for(size_t i=0;i<order.size();i++){int index=order[i];later(250+i*interval,[this,replay,index,i]{s.slot=i;s.gap=replay&&has(s.gaps,index);s.pulse=s.gap?0:s.sequence[index];});later(250+i*interval+std::lround(interval*.6),[this]{s.pulse=0;});}later(300+order.size()*interval,[this,replay]{s.pulse=0;s.gap=false;if(!replay)later(700,[this]{missingPlayback(true);});else{s.phase=Phase::MissingInput;deadline(hard()?std::lround((int[]){0,0,2600,1900,1300}[s.difficulty]*pace()):0);}});}
void GameEngine::missingPress(int n){if(n!=s.answers[s.index]){fail("KUNCI HILANG SALAH");return;}s.index++;points(40);if(sound)sound("correct");if(s.index==int(s.answers.size()))clear();else deadline(std::lround((int[]){0,0,2600,1900,1300}[s.difficulty]*pace()));}
void GameEngine::decoder(){int d=s.difficulty;s.bitCount=(int[]){4,4,5,6,7}[d];int range=1<<s.bitCount;s.invert=d>=3;s.lsb=d==4;for(int i=0;i<std::min(6,(int[]){1,1,2,3,3}[d]+extra());i++){std::vector<int>choices;for(int n=0;n<range;n++)if(!has(s.recent,n))choices.push_back(n);int n=choices[rnd(choices.size())];s.answers.push_back(n);s.recent.push_back(n);if(s.recent.size()>4)s.recent.erase(s.recent.begin());}s.signalKey=int(std::find(s.palette.begin(),s.palette.end(),KeyColors[1])-s.palette.begin())+1;s.answerWindow=d==0?0:std::max(7000,int(std::lround((int[]){0,20000,16000,13000,11000}[d]*std::max(.65f,std::pow(.97f,float(stage()))))));s.phase=Phase::DecoderWatch;int interval=std::max(140,int(std::lround((int[]){800,600,400,300,230}[d]*pace()))),i=0;for(size_t group=0;group<s.answers.size();group++){for(int slot=0;slot<s.bitCount;slot++){int bit=(s.answers[group]>>(s.lsb?slot:s.bitCount-1-slot))&1;if(s.invert)bit=1-bit;later(250+i*interval,[this,bit,group,slot]{s.bit=bit;s.group=group;s.slot=slot;if(sound)sound(bit?"high":"low");});later(250+i*interval+std::lround(interval*.65),[this]{s.bit=-1;});i++;}later(250+i*interval,[this,group]{s.bit=-1;s.group=group;s.slot=s.bitCount;});i++;}later(300+i*interval,[this]{s.phase=Phase::DecoderInput;s.bit=-1;deadline(s.answerWindow);});}
void GameEngine::decoderPress(int n){if(n==2||n==5)s.digits[s.digitIndex]=(s.digits[s.digitIndex]+(n==5?9:1))%10;else if(n==1||n==3)s.digitIndex=(s.digitIndex+(n==1?2:1))%3;else if(n==4)s.digits[s.digitIndex]=0;else if(n==6){if(s.digits[0]*100+s.digits[1]*10+s.digits[2]!=s.answers[s.index]){fail("KODE TIDAK COCOK");return;}s.index++;points(45+s.bitCount*5);if(sound)sound("correct");if(s.index==int(s.answers.size())){clear();return;}s.digits={0,0,0};s.digitIndex=2;deadline(s.answerWindow);}}
}
